function prepareEnding(run){
 const archive=run.metaSnapshot.fragments.map(f=>f.id);
 const release=(archive.some(id=>id.startsWith('box-1'))&&archive.some(id=>id.startsWith('box-2')))||(archive.includes('radio')&&archive.includes('wallet'));
 run.stage='ending';run.endingOptions=[
 {id:'publish',name:'箱を公開する',description:'企業の署名ごと、名簿を街へ流す。誰も証拠を独占できなくなる。',locked:false},
 {id:'seal',name:'箱を封じる',description:'証人を守るため原本を隠し、今夜は生きて帰る。真実は次の夜に託す。',locked:false},
 {id:'release',name:'名前を返す',description:'断片を照合し、名簿の人々へ身元と記憶を返す。企業の争奪戦を終わらせる。',locked:!release,requirement:'過去ランの「鍵の裏面」＋「沈む名前」、またはラジオと身分証の断片を集める。'}];return run;
}
export function endRun(run,reason,won=false){run.stage='result';const credit=run.summary.nights+run.summary.bosses*5+run.summary.personal*3+(won?15:0);const company=run.alliance||'mitsukane';const endings={mitsukane:'鋼鉄の契約書は破れた。ナカガワの名と、消された労働者の名前が同じニュースに並ぶ。',verde:run.mission?.mercy?'被検体は自分の名前で証言した。救えた命が、街の夜明けを変えた。':'治験名簿が公開された。ヴェルデの広告の下に、帰ってこない人々の名が刻まれる。',hakuro:'保守回線に流した名簿は、数百万の端末へ複製された。もう消去命令は届かない。'};run.result={won,reason,credit:Math.max(1,credit),epilogue:won?(run.ending==='seal'?'原本は隠れ家の壁の中に眠る。名簿の人々には逃げ道を渡した。いつか、彼ら自身が真実を語るだろう。':run.ending==='release'?'失われた名前と記憶を持ち主へ返した。箱は誰の武器にもならず、街の人々の人生になった。':endings[company]):'箱は、まだ開いていない。次のフィクサーが、この街の雨を受け継ぐ。',after:run.team.filter(ACTIVE).map(r=>`${r.name}は${r.humanity<=15?'自分の声を取り戻すため、鏡の前に座った。':r.personalDone?'過去と決別し、自分の明日を選んだ。':'夜明けの屋台で、次の仕事を待っている。'}`)};return run;}
